{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors during value updates.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_stage1 = alpha_pos if delta_stage1 > 0 else alpha_neg\n        q_stage1_mf[action_1[trial]] += alpha_stage1 * delta_stage1\n\n        delta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\n        alpha_stage2 = alpha_pos if delta_stage2 > 0 else alpha_neg\n        q_stage2_mf[state_idx, action_2[trial]] += alpha_stage2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Unchosen Q-values in both stages decay towards their initial value of 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_stage1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_stage1] += decay * (0.5 - q_stage1_mf[unchosen_stage1])\n\n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] += decay * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free values are updated by the stage 2 prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha_stage2 * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_bias",
      "title": "Stage 1 Bias",
      "description": "A constant bias is added to the logit of choosing spaceship 0 in stage 1 to capture a baseline preference.",
      "params": [
        {
          "name": "bias",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1[0] += bias  # Add bias for choosing spaceship 0",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage 1 values are computed as a weighted combination of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    }
  ]
}
